// Initialize the number of bits
binfo->nbits = nbits;

// Calculate the number of groups needed
size_t ngroups = BITMAP_BITS2GROUPS(nbits);

// Determine the number of levels in the bitmap tree
size_t nlevels = 0;
if (BITMAP_GROUPS_L0(nbits) > 0) nlevels++;
if (BITMAP_GROUPS_L1(nbits) > 0) nlevels++;
if (BITMAP_GROUPS_L2(nbits) > 0) nlevels++;
if (BITMAP_GROUPS_L3(nbits) > 0) nlevels++;
if (BITMAP_GROUPS_L4(nbits) > 0) nlevels++;

// Store the number of levels
binfo->nlevels = nlevels;

// Initialize the levels array
size_t cumulative_groups = 0;
if (nlevels > 0) {
    binfo->levels[0] = 0;
    cumulative_groups += BITMAP_GROUPS_L0(nbits);
}
if (nlevels > 1) {
    binfo->levels[1] = cumulative_groups;
    cumulative_groups += BITMAP_GROUPS_L1(nbits);
}
if (nlevels > 2) {
    binfo->levels[2] = cumulative_groups;
    cumulative_groups += BITMAP_GROUPS_L2(nbits);
}
if (nlevels > 3) {
    binfo->levels[3] = cumulative_groups;
    cumulative_groups += BITMAP_GROUPS_L3(nbits);
}
if (nlevels > 4) {
    binfo->levels[4] = cumulative_groups;
}

